package ui

import (
	"fmt"
	"sync"

	"github.com/diamondburned/gotk4/pkg/gdk/v4"
	"github.com/diamondburned/gotk4/pkg/gtk/v4"
)

// WordData holds the data for a single transcribed word.
// It includes the text, timestamp, and index for synchronization.
type WordData struct {
	Text      string  // The word text
	StartTime float64 // Start timestamp in seconds
	EndTime   float64 // End timestamp in seconds
	Index     int     // Position in the word list
}

// WordLabel is a clickable label widget for displaying a single transcription word.
// It supports highlighting, hover effects, and click signals for video synchronization.
type WordLabel struct {
	label       *gtk.Label
	data        WordData
	highlighted bool
	hovered     bool
	selected    bool
	isFiller    bool
	mu          sync.RWMutex

	// clickCallbacks stores functions to call when the word is clicked
	clickCallbacks []func(startTime float64, index int)
}

// NewWordLabel creates a new clickable word label with the given word data.
// The label is styled with the "word-label" CSS class and emits click signals.
func NewWordLabel(data WordData) *WordLabel {
	label := gtk.NewLabel(data.Text + " ") // Add space for natural text flow
	label.AddCSSClass("word-label")
	label.SetCursor(gdk.NewCursorFromName("pointer", nil))

	w := &WordLabel{
		label:          label,
		data:           data,
		clickCallbacks: make([]func(startTime float64, index int), 0),
	}

	// Setup click gesture
	clickGesture := gtk.NewGestureClick()
	clickGesture.SetButton(1) // Left mouse button
	clickGesture.ConnectReleased(func(nPress int, x, y float64) {
		w.emitClick()
	})
	label.AddController(clickGesture)

	// Setup hover controller
	hoverController := gtk.NewEventControllerMotion()
	hoverController.ConnectEnter(func(x, y float64) {
		w.setHover(true)
	})
	hoverController.ConnectLeave(func() {
		w.setHover(false)
	})
	label.AddController(hoverController)

	// Setup keyboard activation (Enter/Space)
	keyController := gtk.NewEventControllerKey()
	keyController.ConnectKeyPressed(func(keyval uint, keycode uint, state gdk.ModifierType) bool {
		if keyval == uint(gdk.KEY_Return) || keyval == uint(gdk.KEY_KP_Enter) || keyval == uint(gdk.KEY_space) {
			w.emitClick()
			return true
		}
		return false
	})
	label.AddController(keyController)

	// Set accessible tooltip for screen readers
	label.SetTooltipText(fmt.Sprintf("Word: %s at %.2fs", data.Text, data.StartTime))

	return w
}

// Widget returns the underlying GTK label widget.
// Use this to add the word label to a container.
func (w *WordLabel) Widget() *gtk.Label {
	return w.label
}

// SetData updates the word data associated with this label.
func (w *WordLabel) SetData(data WordData) {
	w.mu.Lock()
	w.data = data
	w.mu.Unlock()
	w.label.SetText(data.Text + " ")
}

// GetData returns the word data associated with this label.
func (w *WordLabel) GetData() WordData {
	w.mu.RLock()
	defer w.mu.RUnlock()
	return w.data
}

// SetHighlighted sets the highlighted state of the word.
// When highlighted, the word gets the "word-highlighted" CSS class.
func (w *WordLabel) SetHighlighted(highlighted bool) {
	w.mu.Lock()
	w.highlighted = highlighted
	w.mu.Unlock()

	if highlighted {
		w.label.AddCSSClass("word-highlighted")
	} else {
		w.label.RemoveCSSClass("word-highlighted")
	}
}

func (w *WordLabel) SetFiller(isFiller bool) {
	w.mu.Lock()
	w.isFiller = isFiller
	w.mu.Unlock()

	if isFiller {
		w.label.AddCSSClass("word-filler")
	} else {
		w.label.RemoveCSSClass("word-filler")
	}
}

func (w *WordLabel) IsFiller() bool {
	w.mu.RLock()
	defer w.mu.RUnlock()
	return w.isFiller
}

// IsHighlighted returns true if the word is currently highlighted.
func (w *WordLabel) IsHighlighted() bool {
	w.mu.RLock()
	defer w.mu.RUnlock()
	return w.highlighted
}

// setHover sets the hover state of the word (internal use).
func (w *WordLabel) setHover(hovered bool) {
	w.mu.Lock()
	w.hovered = hovered
	w.mu.Unlock()

	if hovered {
		w.label.AddCSSClass("word-hover")
	} else {
		w.label.RemoveCSSClass("word-hover")
	}
}

// IsHovered returns true if the mouse is currently over the word.
func (w *WordLabel) IsHovered() bool {
	w.mu.RLock()
	defer w.mu.RUnlock()
	return w.hovered
}

// ConnectClick registers a callback to be invoked when the word is clicked.
// The callback receives the word's start time and index.
func (w *WordLabel) ConnectClick(callback func(startTime float64, index int)) {
	w.mu.Lock()
	defer w.mu.Unlock()
	w.clickCallbacks = append(w.clickCallbacks, callback)
}

// emitClick triggers all registered click callbacks.
// This is called internally when the word is clicked.
func (w *WordLabel) emitClick() {
	w.mu.RLock()
	callbacks := make([]func(startTime float64, index int), len(w.clickCallbacks))
	copy(callbacks, w.clickCallbacks)
	startTime := w.data.StartTime
	idx := w.data.Index
	w.mu.RUnlock()

	for _, cb := range callbacks {
		cb(startTime, idx)
	}
}

// SetSelected sets the selected state of the word for segment export.
func (w *WordLabel) SetSelected(selected bool) {
	w.mu.Lock()
	w.selected = selected
	w.mu.Unlock()

	if selected {
		w.label.AddCSSClass("word-selected")
	} else {
		w.label.RemoveCSSClass("word-selected")
	}
}

// IsSelected returns true if the word is currently selected.
func (w *WordLabel) IsSelected() bool {
	w.mu.RLock()
	defer w.mu.RUnlock()
	return w.selected
}

// SetVisible sets the visibility of the word label.
func (w *WordLabel) SetVisible(visible bool) {
	w.label.SetVisible(visible)
}

package ui

import (
	"sync"

	"github.com/diamondburned/gotk4/pkg/glib/v2"
	"github.com/diamondburned/gotk4/pkg/gtk/v4"
)

const DefaultPoolSize = 100

type VirtualizedWordContainer struct {
	flowBox       *gtk.FlowBox
	words         []WordData
	poolSize      int
	pool          []*WordLabel
	attachedCount int

	mu sync.RWMutex

	onWordClick        func(startTime float64, index int)
	onWordHighlight    func(index int)
	onSelectionChanged func(start, end int)
	highlightedPoolIdx int
	highlightedWordIdx int

	selectionStart int
	selectionEnd   int
	isSelecting    bool

	scrollOffset float64
	visibleRatio float64

	fillerIndices map[int]bool
}

func NewVirtualizedWordContainer(words []WordData) *VirtualizedWordContainer {
	flowBox := gtk.NewFlowBox()
	flowBox.SetSelectionMode(gtk.SelectionNone)
	flowBox.SetRowSpacing(4)
	flowBox.SetColumnSpacing(2)
	flowBox.SetHomogeneous(false)
	flowBox.AddCSSClass("word-container")

	pool := make([]*WordLabel, DefaultPoolSize)
	for i := range pool {
		pool[i] = NewWordLabel(WordData{Text: ""})
		pool[i].SetVisible(false)
	}

	vwc := &VirtualizedWordContainer{
		flowBox:            flowBox,
		words:              words,
		poolSize:           DefaultPoolSize,
		pool:               pool,
		attachedCount:      0,
		scrollOffset:       0,
		visibleRatio:       0.1,
		highlightedPoolIdx: -1,
		highlightedWordIdx: -1,
		selectionStart:     -1,
		selectionEnd:       -1,
	}

	return vwc
}

func (vwc *VirtualizedWordContainer) Widget() *gtk.FlowBox {
	return vwc.flowBox
}

func (vwc *VirtualizedWordContainer) SetWordClickHandler(handler func(startTime float64, index int)) {
	vwc.mu.Lock()
	defer vwc.mu.Unlock()
	vwc.onWordClick = handler
}

func (vwc *VirtualizedWordContainer) SetHighlightedWord(index int) {
	vwc.mu.Lock()
	defer vwc.mu.Unlock()

	if vwc.highlightedPoolIdx >= 0 && vwc.highlightedPoolIdx < len(vwc.pool) {
		vwc.pool[vwc.highlightedPoolIdx].SetHighlighted(false)
	}

	if index < 0 || index >= len(vwc.words) {
		vwc.highlightedPoolIdx = -1
		vwc.highlightedWordIdx = -1
		return
	}

	scrollOffset := vwc.scrollOffset
	visibleRatio := vwc.visibleRatio
	words := vwc.words
	startIdx := vwc.firstVisibleWordIndex(words, scrollOffset, visibleRatio)
	endIdx := vwc.lastVisibleWordIndex(words, scrollOffset, visibleRatio)
	visibleCount := endIdx - startIdx + 1
	if visibleCount > vwc.poolSize {
		visibleCount = vwc.poolSize
	}

	if index < startIdx || index > endIdx {
		vwc.highlightedPoolIdx = -1
		vwc.highlightedWordIdx = index
		return
	}

	poolIdx := index - startIdx
	if poolIdx >= 0 && poolIdx < visibleCount && poolIdx < len(vwc.pool) {
		vwc.pool[poolIdx].SetHighlighted(true)
		vwc.highlightedPoolIdx = poolIdx
		vwc.highlightedWordIdx = index
	} else {
		vwc.highlightedPoolIdx = -1
		vwc.highlightedWordIdx = index
	}
}

func (vwc *VirtualizedWordContainer) GetWordCount() int {
	vwc.mu.RLock()
	defer vwc.mu.RUnlock()
	return len(vwc.words)
}

func (vwc *VirtualizedWordContainer) GetHighlightedWord() int {
	vwc.mu.RLock()
	defer vwc.mu.RUnlock()
	return vwc.highlightedWordIdx
}

func (vwc *VirtualizedWordContainer) SetWords(words []WordData) {
	vwc.mu.Lock()
	defer vwc.mu.Unlock()
	vwc.words = words
}

func (vwc *VirtualizedWordContainer) SetFillerIndices(indices map[int]bool) {
	vwc.mu.Lock()
	defer vwc.mu.Unlock()
	vwc.fillerIndices = indices
}

func (vwc *VirtualizedWordContainer) Clear() {
	vwc.mu.Lock()
	defer vwc.mu.Unlock()
	vwc.words = vwc.words[:0]
	vwc.scrollOffset = 0
}

func (vwc *VirtualizedWordContainer) GetWords() []WordData {
	vwc.mu.RLock()
	defer vwc.mu.RUnlock()
	return vwc.words
}

func (vwc *VirtualizedWordContainer) UpdateViewport(scrollOffset, visibleRatio float64) {
	vwc.mu.Lock()
	defer vwc.mu.Unlock()
	vwc.scrollOffset = scrollOffset
	vwc.visibleRatio = visibleRatio
}

func (vwc *VirtualizedWordContainer) UpdateVisibleWidgets() {
	vwc.mu.Lock()
	scrollOffset := vwc.scrollOffset
	visibleRatio := vwc.visibleRatio
	words := vwc.words
	poolSize := vwc.poolSize
	vwc.mu.Unlock()

	if len(words) == 0 {
		return
	}

	startIdx := vwc.firstVisibleWordIndex(words, scrollOffset, visibleRatio)
	endIdx := vwc.lastVisibleWordIndex(words, scrollOffset, visibleRatio)

	if startIdx > endIdx {
		return
	}

	visibleCount := endIdx - startIdx + 1
	if visibleCount > poolSize {
		visibleCount = poolSize
		endIdx = startIdx + visibleCount - 1
	}

	vwc.mu.Lock()
	vwc.attachedCount = visibleCount
	vwc.mu.Unlock()

	glib.IdleAdd(func() bool {
		vwc.mu.Lock()
		currentAttached := vwc.attachedCount
		currentPool := vwc.pool
		currentFlowBox := vwc.flowBox
		currentWords := vwc.words
		currentStartIdx := vwc.firstVisibleWordIndex(currentWords, vwc.scrollOffset, vwc.visibleRatio)
		vwc.mu.Unlock()

		currentFlowBox.RemoveAll()

		for i := 0; i < currentAttached && i < len(currentPool); i++ {
			wordIdx := currentStartIdx + i
			if wordIdx < len(currentWords) {
				wordData := currentWords[wordIdx]
				wordData.Index = wordIdx
				currentPool[i].SetData(wordData)
				currentPool[i].SetHighlighted(false)
				currentPool[i].SetFiller(vwc.fillerIndices[wordIdx])
				currentPool[i].SetVisible(true)
				currentFlowBox.Append(currentPool[i].Widget())
			}
		}

		return false
	})
}

func (vwc *VirtualizedWordContainer) BindScrollEvents(scrolledWindow *gtk.ScrolledWindow) {
	vscrolled := scrolledWindow.VAdjustment()
	if vscrolled == nil {
		return
	}

	vscrolled.ConnectValueChanged(func() {
		value := vscrolled.Value()
		upper := vscrolled.Upper()
		var scrollOffset float64
		if upper > 0 {
			scrollOffset = value / upper
		} else {
			scrollOffset = 0
		}

		pageSize := vscrolled.PageSize()
		var pageRatio float64
		if upper > 0 {
			pageRatio = pageSize / upper
		} else {
			pageRatio = 0
		}

		vwc.UpdateViewport(scrollOffset, pageRatio)
		vwc.UpdateVisibleWidgets()
	})
}

func (vwc *VirtualizedWordContainer) GetPoolSize() int {
	vwc.mu.RLock()
	defer vwc.mu.RUnlock()
	return vwc.poolSize
}

func (vwc *VirtualizedWordContainer) GetAttachedCount() int {
	vwc.mu.RLock()
	defer vwc.mu.RUnlock()
	return vwc.attachedCount
}

func (vwc *VirtualizedWordContainer) SetSelectionMode(enabled bool) {
	vwc.mu.Lock()
	defer vwc.mu.Unlock()
	vwc.isSelecting = enabled
	if !enabled {
		vwc.clearSelection()
	}
}

func (vwc *VirtualizedWordContainer) IsSelectionMode() bool {
	vwc.mu.RLock()
	defer vwc.mu.RUnlock()
	return vwc.isSelecting
}

func (vwc *VirtualizedWordContainer) StartSelection(index int) {
	vwc.mu.Lock()
	defer vwc.mu.Unlock()
	if index < 0 || index >= len(vwc.words) {
		return
	}
	vwc.selectionStart = index
	vwc.selectionEnd = index
	vwc.notifySelectionChanged()
}

func (vwc *VirtualizedWordContainer) ExtendSelection(index int) {
	vwc.mu.Lock()
	defer vwc.mu.Unlock()
	if index < 0 || index >= len(vwc.words) {
		return
	}
	vwc.selectionEnd = index
	vwc.notifySelectionChanged()
}

func (vwc *VirtualizedWordContainer) ClearSelection() {
	vwc.mu.Lock()
	defer vwc.mu.Unlock()
	vwc.clearSelection()
}

func (vwc *VirtualizedWordContainer) clearSelection() {
	vwc.selectionStart = -1
	vwc.selectionEnd = -1
	vwc.notifySelectionChanged()
}

func (vwc *VirtualizedWordContainer) notifySelectionChanged() {
	if vwc.onSelectionChanged != nil {
		start := vwc.selectionStart
		end := vwc.selectionEnd
		if start > end {
			start, end = end, start
		}
		vwc.onSelectionChanged(start, end)
	}
}

func (vwc *VirtualizedWordContainer) GetSelection() (int, int) {
	vwc.mu.RLock()
	defer vwc.mu.RUnlock()
	start := vwc.selectionStart
	end := vwc.selectionEnd
	if start > end {
		start, end = end, start
	}
	return start, end
}

func (vwc *VirtualizedWordContainer) HasSelection() bool {
	vwc.mu.RLock()
	defer vwc.mu.RUnlock()
	return vwc.selectionStart >= 0 && vwc.selectionEnd >= 0
}

func (vwc *VirtualizedWordContainer) SetSelectionChangedHandler(handler func(start, end int)) {
	vwc.mu.Lock()
	defer vwc.mu.Unlock()
	vwc.onSelectionChanged = handler
}

func (vwc *VirtualizedWordContainer) firstVisibleWordIndex(words []WordData, scrollOffset float64, visibleRatio float64) int {
	if len(words) == 0 {
		return 0
	}

	duration := words[len(words)-1].EndTime
	if duration <= 0 {
		return 0
	}

	targetTime := scrollOffset * duration

	low, high := 0, len(words)-1
	result := low

	for low <= high {
		mid := (low + high) / 2
		wordEnd := words[mid].EndTime
		if wordEnd <= targetTime {
			result = mid + 1
			low = mid + 1
		} else {
			high = mid - 1
		}
	}

	return result
}

func (vwc *VirtualizedWordContainer) lastVisibleWordIndex(words []WordData, scrollOffset float64, visibleRatio float64) int {
	if len(words) == 0 {
		return 0
	}

	duration := words[len(words)-1].EndTime
	if duration <= 0 {
		return len(words) - 1
	}

	targetTime := scrollOffset * duration
	visibleDuration := visibleRatio * duration
	maxTime := targetTime + visibleDuration

	low, high := 0, len(words)-1
	result := low

	for low <= high {
		mid := (low + high) / 2
		wordStart := words[mid].StartTime
		if wordStart < maxTime {
			result = mid
			low = mid + 1
		} else {
			high = mid - 1
		}
	}

	return result
}

